// ---------------------------------------------------------------
// Silent Failure Detection
// Watches for the ABSENCE of expected events, not for errors.
// ---------------------------------------------------------------

const CONFIG = {
  timestampField: 'timestamp',   // column name holding the event time
  eventName: 'contact form submission',
  checkWindowHours: 4,
  minHistoryDays: 14,
  sensitivity: 0.25,             // alert if actual < 25% of expected
  minExpectedToAlert: 1.5,       // ignore normally-quiet windows
  consecutiveWindows: 2,         // confirm before alerting (kills false alarms)
  businessHours: { start: 9, end: 18 },
  businessDays: [1, 2, 3, 4, 5], // JS: Sun=0 ... Sat=6
};

const now = new Date();

// --- parse events -------------------------------------------------
// Google Sheets strips leading zeros from hours ("9:39" not "09:39"), which
// makes naive ISO parsing return Invalid Date and silently drop those rows.
// This parser handles the formats real spreadsheets actually produce.
function parseTs(raw) {
  if (raw === null || raw === undefined || raw === '') return null;
  const s = String(raw).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[T ](\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +(m[6] || 0));
  m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (m) return new Date(+m[3], +m[1] - 1, +m[2], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

const events = [];
let skipped = 0;
for (const item of $input.all()) {
  const d = parseTs(item.json[CONFIG.timestampField]);
  if (d) { events.push(d); } else { skipped++; }
}
events.sort((a, b) => a - b);

if (skipped > 0) {
  console.log(`Warning: ${skipped} row(s) had unreadable timestamps and were skipped.`);
}

if (events.length === 0) {
  return [{ json: { status: 'no_data', alert: false, message: 'No events found in source.' } }];
}

const historyDays = (now - events[0]) / 86400000;
if (historyDays < CONFIG.minHistoryDays) {
  return [{ json: { status: 'learning', alert: false,
    message: `Only ${historyDays.toFixed(1)} days of history; need ${CONFIG.minHistoryDays}.` } }];
}

// --- baseline: median events per (weekday, window), zeros included ---
const W = CONFIG.checkWindowHours;
const windowsPerDay = 24 / W;
const historyEnd = new Date(now.getTime() - 86400000); // exclude today

const counts = {};                       // "YYYY-MM-DD|key" -> count
for (const e of events) {
  if (e >= historyEnd) continue;
  const key = `${e.getDay()}-${Math.floor(e.getHours() / W)}`;
  const dk = `${e.toISOString().slice(0, 10)}|${key}`;
  counts[dk] = (counts[dk] || 0) + 1;
}

const perKey = {};
for (let d = new Date(events[0]); d < historyEnd; d.setDate(d.getDate() + 1)) {
  const dayStr = d.toISOString().slice(0, 10);
  for (let w = 0; w < windowsPerDay; w++) {
    const key = `${d.getDay()}-${w}`;
    (perKey[key] = perKey[key] || []).push(counts[`${dayStr}|${key}`] || 0);
  }
}

const median = arr => {
  const s = [...arr].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

// --- evaluate recent windows -------------------------------------
const inBusinessHours = d =>
  CONFIG.businessDays.includes(d.getDay()) &&
  d.getHours() >= CONFIG.businessHours.start &&
  d.getHours() < CONFIG.businessHours.end;

const judged = [];
for (let i = 0; i < CONFIG.consecutiveWindows * 12; i++) {
  if (judged.length >= CONFIG.consecutiveWindows) break;

  const wEnd = new Date(now.getTime() - i * W * 3600000);
  const wStart = new Date(wEnd.getTime() - W * 3600000);
  if (!inBusinessHours(wStart)) continue;

  const key = `${wStart.getDay()}-${Math.floor(wStart.getHours() / W)}`;
  const hist = perKey[key];
  if (!hist || hist.length < 2) continue;

  const expected = median(hist);
  if (expected < CONFIG.minExpectedToAlert) continue;

  const actual = events.filter(e => e >= wStart && e < wEnd).length;
  judged.push({ expected, actual, anomalous: (actual / expected) < CONFIG.sensitivity });
}

if (judged.length < CONFIG.consecutiveWindows) {
  return [{ json: { status: 'unknown', alert: false, message: 'Not enough comparable windows.' } }];
}

const confirmed = judged.every(j => j.anomalous);
const last = events[events.length - 1];
const silentHours = ((now - last) / 3600000).toFixed(1);

return [{ json: {
  status: confirmed ? 'alert' : 'healthy',
  alert: confirmed,
  eventName: CONFIG.eventName,
  silentHours,
  lastEvent: last.toISOString().replace('T', ' ').slice(0, 16),
  totalExpected: judged.reduce((s, j) => s + j.expected, 0).toFixed(1),
  totalActual: judged.reduce((s, j) => s + j.actual, 0),
  windowsChecked: judged.length,
} }];

