// Build the final alert. Falls back to a plain summary if the AI call failed.
const detection = $('Detect Silent Failure').first().json;
let diagnosis = '';

try {
  diagnosis = $json.content[0].text.trim();
} catch (e) {
  diagnosis = `No ${detection.eventName}s received for ${detection.silentHours} hours. `
    + `About ${detection.totalExpected} were expected; ${detection.totalActual} arrived.\n\n`
    + `Likely causes: a recent website or plugin update broke it; notification emails are `
    + `being blocked or sent to an old address; or the provider had an outage.\n\n`
    + `First check: submit one yourself and confirm it arrives.`;
}

const subject = `Alert: ${detection.eventName}s have stopped (${detection.silentHours}h)`;
const body = `${diagnosis}\n\n---\nLast received: ${detection.lastEvent}\n`
  + `Expected in this period: ~${detection.totalExpected}\nActually received: ${detection.totalActual}\n`
  + `\nThis is an automated check from Silent Failure Monitor.`;

return [{ json: { subject, body, ...detection } }];

// Healthy path: log the check so there's a record the monitor ran.
console.log(`[${new Date().toISOString()}] Healthy - ${$json.totalActual} events vs ~${$json.totalExpected} expected.`);
return [{ json: { logged: true, ...$json } }];
